def solve(inputs: dict) -> float:
    mod, k = int(inputs['MOD']), int(inputs['K'])
    b = [[int(inputs['A']) % mod, int(inputs['B']) % mod],
         [int(inputs['C']) % mod, int(inputs['D']) % mod]]
    r = [[1, 0], [0, 1]]
    def mul(x, y):
        return [[sum(x[i][t] * y[t][j] for t in range(2)) % mod for j in range(2)] for i in range(2)]
    while k:
        if k & 1: r = mul(r, b)
        b = mul(b, b)
        k >>= 1
    return float(sum(map(sum, r)))

